class Solution:
    def countCommas(self, n):
        ans, d, lo = 0, 1, 1
        while lo <= n:
            hi = min(n, lo * 10 - 1)
            ans += (hi - lo + 1) * ((d - 1) // 3)
            d += 1
            lo *= 10
        return ans

c.cpp:
class Solution {
public:
    long long countCommas(long long n) {
        long long ans = 0, d = 1, lo = 1;
        while (lo <= n) {
            long long hi = min(n, lo * 10 - 1);
            ans += (hi - lo + 1) * ((d - 1) / 3);
            d++; lo *= 10;
        }
        return ans;
    }
};

