var countCommas = function(n) {
    let ans = 0, d = 1, lo = 1;
    while (lo <= n) {
        const hi = Math.min(n, lo * 10 - 1);
        ans += (hi - lo + 1) * Math.floor((d - 1) / 3);
        d++; lo *= 10;
    }
    return ans;
};
